<?php
require_once __DIR__ . '/includes/layout.php';
require_role(['super_admin', 'admin']);
$stats = [];
foreach (['members' => 'SELECT COUNT(*) c FROM members WHERE deleted_at IS NULL', 'income' => 'SELECT COALESCE(SUM(amount),0) c FROM contributions', 'expenses' => 'SELECT COALESCE(SUM(amount),0) c FROM expenses', 'projects' => 'SELECT COUNT(*) c FROM projects'] as $key => $query) $stats[$key] = db()->query($query)->fetch_assoc()['c'];
$recentContributions = db()->query('SELECT c.receipt_no,c.amount,c.payment_date,c.contribution_type,m.full_name FROM contributions c JOIN members m ON m.id=c.member_id ORDER BY c.created_at DESC LIMIT 6');
$notes = db()->query('SELECT * FROM notifications WHERE user_id IS NULL ORDER BY created_at DESC LIMIT 6');
$balance = (float)$stats['income'] - (float)$stats['expenses'];
page_header('Dashboard');
?>
