<div class="dashboard"><section class="dashboard-hero"><div><h2>Welcome to OMMI</h2><p>Here is a quick overview of your organisation’s activity.</p></div><a class="btn" href="contributions/index.php">Record contribution</a></section><section class="metric-grid"><article class="metric"><div class="metric-label">TOTAL MEMBERS <span class="metric-icon">♟</span></div><strong><?= e((string)$stats['members']) ?></strong></article><article class="metric"><div class="metric-label">TOTAL INCOME <span class="metric-icon">↗</span></div><strong><?= money($stats['income']) ?></strong></article><article class="metric"><div class="metric-label">TOTAL EXPENSES <span class="metric-icon">−</span></div><strong><?= money($stats['expenses']) ?></strong></article><article class="metric"><div class="metric-label">ACTIVE PROJECTS <span class="metric-icon">□</span></div><strong><?= e((string)$stats['projects']) ?></strong></article></section><section class="dashboard-columns"><article class="dash-card"><div class="dash-card-head"><div><h2>Recent Contributions</h2><p>The latest payments recorded in the system.</p></div><a href="contributions/index.php">View all</a></div><div class="table-wrap"><table class="dash-table"><thead><tr><th>Member</th><th>Type</th><th>Amount</th><th>Date</th></tr></thead><tbody><?php while ($c=$recentContributions->fetch_assoc()): ?><tr><td><strong><?= e($c['full_name']) ?></strong><span class="receipt"><?= e($c['receipt_no']) ?></span></td><td><span class="type-tag"><?= e($c['contribution_type']) ?></span></td><td class="amount"><?= money($c['amount']) ?></td><td><?= e(date('d M Y', strtotime($c['payment_date']))) ?></td></tr><?php endwhile; ?></tbody></table></div></article><aside><article class="dash-card"><div class="dash-card-head"><div><h2>Notifications</h2><p>Organisation updates.</p></div></div><div class="notifications"><?php while ($n=$notes->fetch_assoc()): ?><div class="notification"><strong><?= e($n['title']) ?></strong><p><?= e($n['body']) ?></p></div><?php endwhile; ?></div></article><div class="balance-card"><span>Available balance</span><strong class="<?= $balance < 0 ? 'negative' : '' ?>"><?= money($balance) ?></strong><small>Total income less recorded expenses</small></div></aside></section></div>
<?php page_footer(); ?>
